<template>
  <div class="exam-room">
    <header class="room-header"><div class="room-brand"><span>YQ</span><div><small>FOCUS EXAM</small><b>{{ exam ? exam.paperName : '正在进入考试' }}</b></div></div><div class="save-indicator" :class="saveState"><i></i>{{ saveText }}</div><div class="countdown" :class="{ urgent: remainingSeconds <= 300 }"><small>剩余时间</small><b>{{ countdownText }}</b></div></header>
    <div v-if="loading" class="room-state"><span class="loading-ring"></span><strong>正在准备试卷</strong></div>
    <div v-else-if="errorMessage" class="room-state error"><strong>无法进入考试</strong><p>{{ errorMessage }}</p><button @click="$router.replace('/exams')">返回考试列表</button></div>
    <main v-else-if="exam" class="room-layout">
      <aside class="question-map"><header><span>答题卡</span><b>{{ answeredCount }}/{{ exam.questions.length }}</b></header><div class="map-grid"><button v-for="(question,index) in exam.questions" :key="question.paperQuestionId" :class="{active:activeIndex===index,answered:isAnswered(question)}" @click="scrollTo(index)">{{ index+1 }}</button></div><div class="map-legend"><span><i class="answered"></i>已答</span><span><i></i>未答</span></div><button class="submit-paper" :disabled="submitting" @click="confirmSubmit">{{ submitting?'正在交卷':'提交试卷' }}</button></aside>
      <section class="question-stream">
        <article v-for="(question,index) in exam.questions" :id="`question-${index}`" :key="question.paperQuestionId" class="question-card" @mouseenter="activeIndex=index">
          <header><span>QUESTION {{ String(index+1).padStart(2,'0') }}</span><div><b>{{ typeLabel(question.questionType) }}</b><small>{{ question.questionScore }} 分</small></div></header><h2>{{ question.questionContent }}</h2>
          <div v-if="question.questionType==='SINGLE'" class="choice-list"><label v-for="option in question.options" :key="option.optionKey" :class="{selected:answers[question.paperQuestionId]===option.optionKey}"><input v-model="answers[question.paperQuestionId]" type="radio" :name="`q-${question.paperQuestionId}`" :value="option.optionKey" @change="queueSave(question)" /><span>{{ option.optionKey }}</span><p>{{ option.optionContent }}</p></label></div>
          <div v-else-if="question.questionType==='MULTIPLE'" class="choice-list"><label v-for="option in question.options" :key="option.optionKey" :class="{selected:(multiAnswers[question.paperQuestionId]||[]).includes(option.optionKey)}"><input v-model="multiAnswers[question.paperQuestionId]" type="checkbox" :value="option.optionKey" @change="queueMultipleSave(question)" /><span>{{ option.optionKey }}</span><p>{{ option.optionContent }}</p></label></div>
          <div v-else-if="question.questionType==='JUDGE'" class="judge-list"><label :class="{selected:answers[question.paperQuestionId]==='TRUE'}"><input v-model="answers[question.paperQuestionId]" type="radio" :name="`q-${question.paperQuestionId}`" value="TRUE" @change="queueSave(question)" />正确</label><label :class="{selected:answers[question.paperQuestionId]==='FALSE'}"><input v-model="answers[question.paperQuestionId]" type="radio" :name="`q-${question.paperQuestionId}`" value="FALSE" @change="queueSave(question)" />错误</label></div>
          <textarea v-else v-model="answers[question.paperQuestionId]" :placeholder="question.questionType==='FILL'?'填写你的答案':'写下完整作答思路'" :rows="question.questionType==='SHORT'?8:4" @input="queueSave(question)" />
          <footer><span v-if="savingQuestions[question.paperQuestionId]">正在保存…</span><span v-else-if="savedQuestions[question.paperQuestionId]">已自动保存</span><span v-else>答案变更后自动保存</span></footer>
        </article>
      </section>
    </main>
  </div>
</template>

<script>
import { startStudentExam, saveStudentExamAnswer, submitStudentExam } from '@/api/exam'
export default{name:'ExamRoom',data(){return{exam:null,loading:true,errorMessage:'',answers:{},multiAnswers:{},savingQuestions:{},savedQuestions:{},saveTimers:{},activeIndex:0,remainingSeconds:0,countdownTimer:null,deadlineTarget:0,submitting:false,leaving:false}},computed:{answeredCount(){if(!this.exam)return 0;return this.exam.questions.filter(this.isAnswered).length},countdownText(){const seconds=Math.max(0,this.remainingSeconds);const h=String(Math.floor(seconds/3600)).padStart(2,'0');const m=String(Math.floor(seconds%3600/60)).padStart(2,'0');const s=String(seconds%60).padStart(2,'0');return`${h}:${m}:${s}`},saveState(){return Object.values(this.savingQuestions).some(Boolean)?'saving':'saved'},saveText(){return this.saveState==='saving'?'正在保存答案':'答案已同步'}},async mounted(){window.addEventListener('beforeunload',this.beforeUnload);await this.loadExam()},beforeDestroy(){window.removeEventListener('beforeunload',this.beforeUnload);clearInterval(this.countdownTimer);Object.values(this.saveTimers).forEach(clearTimeout)},beforeRouteLeave(to,from,next){if(this.leaving||!this.exam||!['IN_PROGRESS'].includes(this.exam.recordStatus))return next();if(window.confirm('考试仍在进行，离开后答案会保留，但倒计时不会暂停。确定离开吗？'))next();else next(false)},methods:{
 async loadExam(){this.loading=true;try{const res=await startStudentExam(this.$route.params.examId);this.exam=res.data;this.exam.questions.forEach(question=>{if(question.questionType==='MULTIPLE')this.$set(this.multiAnswers,question.paperQuestionId,question.savedAnswer?question.savedAnswer.split(',').filter(Boolean):[]);else this.$set(this.answers,question.paperQuestionId,question.savedAnswer||'')});this.setupCountdown()}catch(e){this.errorMessage=e.message}finally{this.loading=false}},setupCountdown(){if(!this.exam.deadlineTime)return;const serverNow=new Date(this.exam.serverTime).getTime();const deadline=new Date(this.exam.deadlineTime).getTime();this.deadlineTarget=Date.now()+Math.max(0,deadline-serverNow);this.tick();this.countdownTimer=setInterval(this.tick,1000)},tick(){this.remainingSeconds=Math.max(0,Math.ceil((this.deadlineTarget-Date.now())/1000));if(this.remainingSeconds===0&&!this.submitting){clearInterval(this.countdownTimer);this.autoSubmit()}},queueSave(question){this.scheduleSave(question,this.answers[question.paperQuestionId]||'')},queueMultipleSave(question){const value=(this.multiAnswers[question.paperQuestionId]||[]).slice().sort().join(',');this.scheduleSave(question,value)},scheduleSave(question,value){const id=question.paperQuestionId;this.$set(this.savedQuestions,id,false);clearTimeout(this.saveTimers[id]);this.saveTimers[id]=setTimeout(()=>this.persistAnswer(id,value),550)},async persistAnswer(id,value){this.$set(this.savingQuestions,id,true);try{await saveStudentExamAnswer(this.exam.recordId,id,value);this.$set(this.savedQuestions,id,true)}catch(e){this.$set(this.savedQuestions,id,false)}finally{this.$set(this.savingQuestions,id,false)}},isAnswered(question){const value=question.questionType==='MULTIPLE'?this.multiAnswers[question.paperQuestionId]:this.answers[question.paperQuestionId];return Array.isArray(value)?value.length>0:Boolean(value&&String(value).trim())},scrollTo(index){this.activeIndex=index;const node=document.getElementById(`question-${index}`);if(node)node.scrollIntoView({behavior:'smooth',block:'start'})},async flushSaves(){const tasks=this.exam.questions.map(question=>{clearTimeout(this.saveTimers[question.paperQuestionId]);const value=question.questionType==='MULTIPLE'?(this.multiAnswers[question.paperQuestionId]||[]).slice().sort().join(','):(this.answers[question.paperQuestionId]||'');return saveStudentExamAnswer(this.exam.recordId,question.paperQuestionId,value)});await Promise.all(tasks)},async confirmSubmit(){const unanswered=this.exam.questions.length-this.answeredCount;const message=unanswered?`还有 ${unanswered} 道题未作答，确定提交吗？`:'提交后不能继续修改答案，确定提交吗？';if(!window.confirm(message))return;await this.finishSubmit()},async autoSubmit(){await this.finishSubmit(true)},async finishSubmit(auto=false){if(this.submitting)return;this.submitting=true;try{await this.flushSaves();await submitStudentExam(this.exam.recordId);this.leaving=true;window.alert(auto?'答题时间已结束，试卷已自动提交':'试卷已提交');this.$router.replace('/exams')}catch(e){if(!auto)window.alert(e.message||'提交失败，系统仍会在后端自动交卷')}finally{this.submitting=false}},beforeUnload(event){if(this.exam&&this.exam.recordStatus==='IN_PROGRESS'&&!this.leaving){event.preventDefault();event.returnValue=''}},typeLabel(value){return{SINGLE:'单选题',MULTIPLE:'多选题',JUDGE:'判断题',FILL:'填空题',SHORT:'简答题'}[value]||value}
}}
</script>

<style scoped>
.exam-room{min-height:100vh;background:#eef5f7}.room-header{height:76px;position:sticky;z-index:20;top:0;display:grid;grid-template-columns:1fr auto 180px;align-items:center;padding:0 34px;border-bottom:1px solid rgba(14,116,144,.18);background:rgba(255,255,255,.95);backdrop-filter:blur(16px)}.room-brand{display:flex;align-items:center;gap:12px}.room-brand>span{width:40px;height:40px;display:grid;place-items:center;border-radius:13px 13px 4px 13px;color:#fff;background:var(--lagoon);font:800 13px var(--display)}.room-brand div{display:flex;flex-direction:column}.room-brand small{color:var(--coral);font:700 8px var(--mono);letter-spacing:.18em}.room-brand b{margin-top:3px;font:700 14px var(--display)}.save-indicator{display:flex;align-items:center;gap:8px;margin-right:28px;color:var(--ink-soft);font-size:10px}.save-indicator i{width:7px;height:7px;border-radius:50%;background:#59b894}.save-indicator.saving i{background:#e7a94d;animation:pulse 1s infinite}.countdown{justify-self:end;display:flex;flex-direction:column;padding-left:22px;border-left:1px solid var(--line)}.countdown small{color:var(--ink-soft);font-size:8px}.countdown b{margin-top:3px;color:var(--lagoon-deep);font:750 20px var(--mono)}.countdown.urgent b{color:var(--coral)}.room-layout{width:min(1240px,calc(100% - 44px));display:grid;grid-template-columns:230px minmax(0,1fr);gap:22px;margin:0 auto;padding:26px 0 70px}.question-map{height:max-content;position:sticky;top:102px;padding:20px;border:1px solid var(--line);border-radius:8px 20px 20px 20px;background:#fff;box-shadow:var(--shadow)}.question-map header{display:flex;justify-content:space-between}.question-map header span{font:700 12px var(--display)}.question-map header b{color:var(--lagoon);font:700 11px var(--mono)}.map-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin-top:17px}.map-grid button{aspect-ratio:1;border:1px solid var(--line);border-radius:7px;color:var(--ink-soft);background:#fff;font:650 10px var(--mono)}.map-grid button.answered{border-color:transparent;color:var(--lagoon-deep);background:var(--mint)}.map-grid button.active{box-shadow:0 0 0 2px var(--coral)}.map-legend{display:flex;gap:15px;margin-top:16px;color:var(--ink-soft);font-size:8px}.map-legend span{display:flex;align-items:center;gap:5px}.map-legend i{width:9px;height:9px;border:1px solid var(--line);border-radius:3px}.map-legend i.answered{border:0;background:var(--mint)}.submit-paper{width:100%;height:41px;margin-top:20px;border:0;border-radius:10px;color:#fff;background:var(--coral);font-size:11px;font-weight:700}.question-stream{display:grid;gap:16px}.question-card{scroll-margin-top:98px;padding:30px 34px 22px;border:1px solid var(--line);border-radius:20px 7px 20px 20px;background:#fff;box-shadow:0 16px 50px -42px rgba(16,42,67,.6)}.question-card>header{display:flex;justify-content:space-between}.question-card>header>span{color:var(--coral);font:700 9px var(--mono);letter-spacing:.14em}.question-card>header div{display:flex;gap:9px}.question-card>header b,.question-card>header small{padding:5px 8px;border-radius:999px;color:var(--lagoon-deep);background:var(--mint);font-size:8px}.question-card>header small{color:var(--ink-soft);background:var(--sky)}.question-card h2{margin-top:18px;font:700 16px/1.75 var(--display)}.choice-list{display:grid;gap:9px;margin-top:22px}.choice-list label{display:grid;grid-template-columns:34px 34px 1fr;align-items:center;min-height:52px;padding:9px 14px;border:1px solid var(--line);border-radius:10px;cursor:pointer;transition:.16s}.choice-list label:hover,.choice-list label.selected{border-color:rgba(14,116,144,.4);background:var(--sky)}.choice-list input{opacity:0}.choice-list label>span{width:27px;height:27px;display:grid;place-items:center;border-radius:8px;color:var(--lagoon-deep);background:var(--mint);font:700 10px var(--mono)}.choice-list p{font-size:12px}.judge-list{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:22px}.judge-list label{padding:18px;border:1px solid var(--line);border-radius:10px;text-align:center}.judge-list label.selected{border-color:var(--lagoon);background:var(--mint)}.judge-list input{margin-right:8px}.question-card textarea{width:100%;margin-top:22px;padding:15px;border:1px solid var(--line);border-radius:10px;outline:0;resize:vertical;line-height:1.8}.question-card textarea:focus{border-color:var(--lagoon);box-shadow:0 0 0 3px rgba(14,116,144,.1)}.question-card footer{margin-top:14px;color:var(--ink-soft);font-size:8px;text-align:right}.room-state{min-height:calc(100vh - 76px);display:grid;place-content:center;gap:12px;text-align:center}.room-state.error button{justify-self:center;padding:9px 14px;border:0;border-radius:8px;color:#fff;background:var(--lagoon)}.loading-ring{width:28px;height:28px;justify-self:center;border:3px solid rgba(14,116,144,.15);border-top-color:var(--lagoon);border-radius:50%;animation:spin .7s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@keyframes pulse{50%{opacity:.35}}
@media(max-width:800px){.room-header{grid-template-columns:1fr auto;padding:0 16px}.save-indicator{display:none}.countdown{width:125px}.room-layout{width:min(100% - 24px,680px);grid-template-columns:1fr}.question-map{position:static}.question-card{padding:24px 20px}}
</style>
